import json, re
from pathlib import Path

files = [
    '/usr/lib/node_modules/openclaw/node_modules/bottleneck/.env',
    '/root/config.json',
    '/root/project/config.json',
    '/root/project/.env',
    '/root/.env',
]

sensitive_key = re.compile(r'(secret|token|key|password|passwd|pwd|credential|auth|api|client_secret|private)', re.I)
assign_re = re.compile(r'^([A-Za-z_][A-Za-z0-9_\.\-]*)(\s*=\s*)(.*)$')

def redact_scalar(v):
    if isinstance(v, str) and v:
        return '<REDACTED>'
    if v is None:
        return None
    return '<REDACTED>'

def redact_json(obj, parent_key=''):
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            if sensitive_key.search(str(k)):
                out[k] = redact_scalar(v)
            else:
                out[k] = redact_json(v, k)
        return out
    if isinstance(obj, list):
        return [redact_json(x, parent_key) for x in obj]
    return obj

for i, f in enumerate(files, 1):
    print(f'===== [{i}/{len(files)}] {f} =====')
    p = Path(f)
    try:
        text = p.read_text(errors='replace')
    except Exception as e:
        print(f'<ERROR reading file: {e}>')
        continue

    if p.name.endswith('.json'):
        try:
            data = json.loads(text)
            print(json.dumps(redact_json(data), indent=2, ensure_ascii=False))
        except Exception:
            # fallback line redaction
            for line in text.splitlines():
                print(line)
    else:
        for line in text.splitlines():
            m = assign_re.match(line)
            if m and sensitive_key.search(m.group(1)) and m.group(3).strip():
                print(m.group(1) + m.group(2) + '<REDACTED>')
            else:
                print(line)
    print()
